#!/usr/bin/env sh
# Generated by edgepoint. Do not edit — run `edgepoint sync` instead.
#
# Applies migrations on the server, in filename order, each exactly once.
# Same tracking table as local development, so the two cannot drift.
set -eu

cd "$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)"

DC="docker compose -f compose.prod.yaml"
psql_q() { $DC exec -T db psql -U postgres -d app -tAq -c "$1" 2>/dev/null | tr -d '[:space:]'; }

[ -d migrations ] || { echo "no migrations directory"; exit 0; }

$DC exec -T db psql -U postgres -d app -v ON_ERROR_STOP=1 -q -c \
  "set client_min_messages to warning;
   create table if not exists _edgepoint_migrations (
     name text primary key,
     applied_at timestamptz not null default now()
   );" >/dev/null 2>&1

applied=0
for file in migrations/*.sql; do
  [ -e "$file" ] || continue
  name="$(basename "$file")"
  [ "$(psql_q "select 1 from _edgepoint_migrations where name = '$name'")" = "1" ] && continue

  echo "  applying $name"
  # ON_ERROR_STOP plus a transaction: a migration either lands completely or
  # not at all. A half-applied schema on production is the worst outcome here.
  $DC exec -T db psql -U postgres -d app -v ON_ERROR_STOP=1 -q --single-transaction \
    < "$file" || { echo "MIGRATION FAILED: $name" >&2; exit 1; }

  $DC exec -T db psql -U postgres -d app -q -c \
    "insert into _edgepoint_migrations (name) values ('$name');" >/dev/null
  applied=$((applied + 1))
done

echo "  ${applied} migration(s) applied"
